def min_operations_to_convert(n, s, t):
    if s == t:
        return 0

    # Check if it's possible to convert s to t
    diff_positions = [i for i in range(n) if s[i] != t[i]]
    if len(diff_positions) % 2 != 0:
        return -1

    # Count the number of '0' to '1' and '1' to '0' transitions in s
    transitions_s = [0] * n
    for i in range(1, n):
        if s[i] != s[i - 1]:
            transitions_s[i] = transitions_s[i - 1] + 1
        else:
            transitions_s[i] = transitions_s[i - 1]

    # Count the number of '0' to '1' and '1' to '0' transitions in t
    transitions_t = [0] * n
    for i in range(1, n):
        if t[i] != t[i - 1]:
            transitions_t[i] = transitions_t[i - 1] + 1
        else:
            transitions_t[i] = transitions_t[i - 1]

    # Calculate the number of operations needed
    operations = 0
    i = n - 1
    while i >= 0:
        if s[i] != t[i]:
            operations += 1
            i -= 2
        else:
            i -= 1

    return operations

